C = './packages/addressing/resources/geography/belgium-postal-codes.csv'
L = './packages/addressing/resources/geography/belgium-postal-code-areas.csv'
fails = []
def check(name, cond, detail=''):
    print(('PASS' if cond else 'FAIL'), name, detail)
    if not cond: fails.append(name)
rows = list(csv.DictReader(open(A, newline='')))
byid = {r['source_id']: r for r in rows}
check('areas-13', len(rows) == 13, str(len(rows)))
check('regions-3', sum(1 for r in rows if r['type'] == 'region') == 3)
check('provinces-10', sum(1 for r in rows if r['type'] == 'province') == 10)
